            /** @description Bắt buộc khi outcome = not_checked */
            not_checked_reason?: components["schemas"]["NotCheckedReason"] | null;
            /** @description Lỗi thực thi khi outcome = failed (timeout, ảnh hỏng, worker lỗi); không chứa secret */
            error?: string | null;
            attempts: number;
